230: function renderNotes() {
231:   toolView.innerHTML = `<div class="tool-heading"><div><span class="tool-eyebrow">MORI WORKSPACE</span><h2>灵感便签</h2><p>把突然想到的点子先收好，内容只保存在这台设备的浏览器里。</p></div><button class="primary-action" data-action="new-note">＋ 写一张便签</button></div><form class="note-editor" id="noteForm"><label for="noteTitle">标题</label><input id="noteTitle" maxlength="80" placeholder="给这份灵感起个名字…" required><label for="noteBody">内容</label><textarea id="noteBody" rows="4" maxlength="2000" placeholder="记下你的想法、计划或想记住的事…" required></textarea><div class="editor-actions"><button type="button" class="quiet-action" data-action="cancel-note">取消</button><button type="submit" class="primary-action">保存便签</button></div></form><div class="note-grid">${notes.length ? notes.map((note) => `<article class="note-card"><div class="note-card-top"><span>✦ 灵感记录</span><button aria-label="删除便签" data-action="delete-note" data-id="${escapeHTML(note.id)}">×</button></div><h3>${escapeHTML(note.title)}</h3><p>${escapeHTML(note.body).replace(/\n/g,'<br>')}</p><time>${escapeHTML(note.date || '')}</time></article>`).join('') : '<div class="empty-state"><span>✎</span><strong>还没有便签</strong><p>把脑海里的小灵感写下来吧。</p></div>'}</div>`;
232:   $('#noteForm').hidden = true;
233: }
234: function renderTasks() {
